import{_ as a,C as r,c as n,o,j as e,G as l,al as c,a as s}from"./chunks/framework.I2ukxCrD.js";const T=JSON.parse('{"title":"串的基本操作","titleTemplate":"数据结构","description":"串的基本操作","frontmatter":{"title":"串的基本操作","titleTemplate":"数据结构","description":"串的基本操作","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false,"tags":["数据结构","串","基本操作","408"]},"headers":[],"relativePath":"post/kaoyan/408/408_DS/04/408_DS_3.md","filePath":"post/kaoyan/408/408_DS/04/408_DS_3.md","lastUpdated":1756123810000}'),i={name:"post/kaoyan/408/408_DS/04/408_DS_3.md"};function S(p,t,g,y,_,x){const d=r("ArticleSummary");return o(),n("div",null,[t[0]||(t[0]=e("h1",{id:"串的基本操作",tabindex:"-1"},[s("串的基本操作 "),e("a",{class:"header-anchor",href:"#串的基本操作","aria-label":'Permalink to "串的基本操作"'},"​")],-1)),l(d,{texts:["本文介绍了串的基本操作的相关内容，包括基本概念、实现方法和应用场景。通过学习这些知识，可以深入理解数据结构的核心原理和实际应用。","串的基本操作是数据结构中的重要内容！本文将为你详细讲解相关的理论知识和实现技巧，帮助你掌握这一关键概念。","想要掌握串的基本操作？本文提供了全面的学习指南，从基础概念到实际应用，让你系统地理解和掌握相关知识。","深入学习串的基本操作的最佳资源！本文详细介绍了相关的理论基础和实践方法，是提升数据结构能力的重要材料。"]}),t[1]||(t[1]=c('<h2 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h2><p>常见的串的基本操作有：</p><table tabindex="0"><thead><tr><th style="text-align:center;">操作</th><th style="text-align:center;">函数原型</th><th>功能描述</th></tr></thead><tbody><tr><td style="text-align:center;">赋值</td><td style="text-align:center;"><code>StrAssign(&amp;T, chars)</code></td><td>把串 T 赋值为 chars</td></tr><tr><td style="text-align:center;">复制</td><td style="text-align:center;"><code>StrCopy(&amp;T, S)</code></td><td>由串 S 复制得到串 T</td></tr><tr><td style="text-align:center;">判空</td><td style="text-align:center;"><code>StrEmpty(S)</code></td><td>若 S 为空串，则返回 TRUE，否则返回 FALSE</td></tr><tr><td style="text-align:center;">比较</td><td style="text-align:center;"><code>StrCompare(S, T)</code></td><td>S&gt;T 返回正数，S=T 返回 0，S&lt;T 返回负数</td></tr><tr><td style="text-align:center;">求串长</td><td style="text-align:center;"><code>StrLength(S)</code></td><td>返回串 S 的元素个数</td></tr><tr><td style="text-align:center;">求子串</td><td style="text-align:center;"><code>SubString(&amp;Sub, S, pos, len)</code></td><td>返回 S 中从 pos 起长 len 的子串</td></tr><tr><td style="text-align:center;">串联接</td><td style="text-align:center;"><code>Concat(&amp;T, S1, S2)</code></td><td>用 T 返回由 S1 和 S2 联接而成的新串</td></tr><tr><td style="text-align:center;">定位</td><td style="text-align:center;"><code>Index(S, T)</code></td><td>返回子串 T 在主串 S 中首次出现的位置，否则返回 0</td></tr><tr><td style="text-align:center;">清空</td><td style="text-align:center;"><code>ClearString(&amp;S)</code></td><td>将 S 清为空串</td></tr><tr><td style="text-align:center;">销毁</td><td style="text-align:center;"><code>DestroyString(&amp;S)</code></td><td>将串 S 销毁</td></tr></tbody></table><p>不同的高级语言对串的基本操作集可以有不同的定义方法。在上述定义的操作中，串赋值 <code>StrAssign</code>、串比较 <code>StrCompare</code>、求串长 <code>StrLength</code>、串联接 <code>Concat</code> 及求子串 <code>SubString</code> 五种操作构成串类型的最小操作子集，即这些操作不可能利用其他串操作来实现；反之，其他串操作（除串清除 <code>ClearString</code> 和串销毁 <code>DestroyString</code> 外）均可在该最小操作子集上实现。</p>',4))])}const h=a(i,[["render",S]]);export{T as __pageData,h as default};
